+function assertNonEmpty(value, fieldName) {
+  if (typeof value !== "string" || value.trim().length === 0) {
+    throw new Error(`${fieldName} is required`);
+  }
+}
+
+export function buildTriggerTaskPayload(subagent, prompt) {
+  assertNonEmpty(subagent, "subagent");
+  assertNonEmpty(prompt, "prompt");
+
+  return {
+    action: "trigger_task",
+    subagent: subagent.trim(),
+    prompt: prompt.trim(),
+  };
+}
+
+export function parseSocketMessage(message) {
+  try {
+    return JSON.parse(message);
+  } catch (_error) {
+    return {
+      type: "invalid_json",
+      message: String(message),
+    };
+  }
+}
+
+export function formatEventSummary(event) {
+  if (event.type === "action_receipt") {
+    const status = event.status ?? "unknown";
+    const detail = event.message ?? "no message";
+    return `任务回执: ${status} - ${detail}`;
+  }
+
+  if (event.type === "system_diagnostics_report") {
+    const count = Array.isArray(event.data) ? event.data.length : 0;
+    return `诊断上报: ${count} 个文件存在错误`;
+  }
+
+  if (event.type === "file_saved") {
+    return `文件已保存: ${event.file ?? "unknown file"}`;
+  }
+
+  if (event.type === "connected") {
+    return "已连接 Trae Worker";
+  }
+
+  return `未分类事件: ${event.type ?? "unknown"}`;
+}
