+import {
+  buildTriggerTaskPayload,
+  formatEventSummary,
+  parseSocketMessage,
+} from "./protocol.mjs";
+
+const MAX_EVENT_COUNT = 120;
+
+const elements = {
+  wsUrlInput: document.querySelector("#wsUrlInput"),
+  connectBtn: document.querySelector("#connectBtn"),
+  disconnectBtn: document.querySelector("#disconnectBtn"),
+  healthBtn: document.querySelector("#healthBtn"),
+  connectionBadge: document.querySelector("#connectionBadge"),
+  statusText: document.querySelector("#statusText"),
+  taskForm: document.querySelector("#taskForm"),
+  subagentInput: document.querySelector("#subagentInput"),
+  promptInput: document.querySelector("#promptInput"),
+  eventFeed: document.querySelector("#eventFeed"),
+  diagnosticsEmpty: document.querySelector("#diagnosticsEmpty"),
+  diagnosticsList: document.querySelector("#diagnosticsList"),
+  quickActionButtons: Array.from(document.querySelectorAll(".chip")),
+};
+
+const state = {
+  socket: null,
+};
+
+function nowTime() {
+  return new Date().toLocaleTimeString("zh-CN", { hour12: false });
+}
+
+function toHealthUrl(wsUrl) {
+  try {
+    const parsed = new URL(wsUrl);
+    parsed.protocol = parsed.protocol === "wss:" ? "https:" : "http:";
+    parsed.pathname = "/health";
+    parsed.search = "";
+    parsed.hash = "";
+    return parsed.toString();
+  } catch (_error) {
+    return "http://127.0.0.1:9090/health";
+  }
+}
+
+function setConnectionStatus(mode, text) {
+  const badge = elements.connectionBadge;
+  badge.classList.remove("badge-online", "badge-offline", "badge-connecting");
+
+  if (mode === "online") {
+    badge.classList.add("badge-online");
+    badge.textContent = "在线";
+  } else if (mode === "connecting") {
+    badge.classList.add("badge-connecting");
+    badge.textContent = "连接中";
+  } else {
+    badge.classList.add("badge-offline");
+    badge.textContent = "离线";
+  }
+
+  elements.statusText.textContent = text;
+}
+
+function classifyEvent(event) {
+  if (event.type === "error" || event.type === "invalid_json") {
+    return "error";
+  }
+
+  if (event.type === "action_receipt") {
+    return event.status === "success" ? "success" : "warn";
+  }
+
+  if (event.type === "health_result" && !event.ok) {
+    return "warn";
+  }
+
+  return "info";
+}
+
+function appendEvent(event) {
+  const card = document.createElement("article");
+  const level = classifyEvent(event);
+  card.className = `event-card event-${level}`;
+
+  const summary = formatEventSummary(event);
+  const kind = event.type ?? "unknown";
+  const timestamp = nowTime();
+
+  const head = document.createElement("div");
+  head.className = "event-card-head";
+  head.innerHTML = `<span>${timestamp}</span><span>${kind}</span>`;
+
+  const title = document.createElement("strong");
+  title.textContent = summary;
+
+  const details = document.createElement("details");
+  details.innerHTML = "<summary>原始数据</summary>";
+  const json = document.createElement("pre");
+  json.textContent = JSON.stringify(event, null, 2);
+  details.appendChild(json);
+
+  card.append(head, title, details);
+  elements.eventFeed.prepend(card);
+
+  while (elements.eventFeed.children.length > MAX_EVENT_COUNT) {
+    elements.eventFeed.removeChild(elements.eventFeed.lastElementChild);
+  }
+}
+
+function renderDiagnostics(data) {
+  const list = elements.diagnosticsList;
+  list.innerHTML = "";
+
+  if (!Array.isArray(data) || data.length === 0) {
+    elements.diagnosticsEmpty.hidden = false;
+    return;
+  }
+
+  elements.diagnosticsEmpty.hidden = true;
+  data.forEach((group) => {
+    const item = document.createElement("li");
+    item.className = "diagnostic-item";
+
+    const file = document.createElement("strong");
+    file.textContent = group.file ?? "unknown file";
+    item.appendChild(file);
+
+    const lines = Array.isArray(group.errors) ? group.errors : [];
+    if (lines.length === 0) {
+      const empty = document.createElement("span");
+      empty.textContent = "无错误详情";
+      item.appendChild(empty);
+    } else {
+      const firstThree = lines.slice(0, 3);
+      firstThree.forEach((entry) => {
+        const row = document.createElement("div");
+        row.textContent = `L${entry.line ?? "?"}: ${entry.message ?? ""}`;
+        item.appendChild(row);
+      });
+
+      if (lines.length > 3) {
+        const more = document.createElement("div");
+        more.textContent = `...其余 ${lines.length - 3} 条省略`;
+        item.appendChild(more);
+      }
+    }
+
+    list.appendChild(item);
+  });
+}
