+}
+
+function connectSocket() {
+  const wsUrl = elements.wsUrlInput.value.trim();
+
+  if (!wsUrl) {
+    appendEvent({ type: "error", message: "WebSocket 地址不能为空。" });
+    return;
+  }
+
+  if (state.socket) {
+    state.socket.close(1000, "reconnect");
+  }
+
+  setConnectionStatus("connecting", `正在连接 ${wsUrl}`);
+
+  try {
+    const socket = new WebSocket(wsUrl);
+    state.socket = socket;
