def get_value(k):
    row = cur.execute('SELECT value FROM ItemTable WHERE key=?', (k,)).fetchone()
    if not row:
        return None
    v=row[0]
    if isinstance(v, bytes):
        v=v.decode('utf-8','ignore')
    return v

# find account prefix
prefixes=[]
for (k,) in cur.execute("SELECT key FROM ItemTable WHERE key LIKE '%_AI.agent.model.selected_model'").fetchall():
    prefixes.append(k.split('_AI.agent.model.selected_model')[0])

for prefix in prefixes:
    print('PREFIX', prefix)
    selected_raw = get_value(prefix + '_AI.agent.model.selected_model')
    try:
        selected = json.loads(selected_raw)
    except Exception:
        selected = selected_raw
    print('SELECTED', selected.get('name') if isinstance(selected, dict) else selected)

    model_list_raw = get_value(prefix + '_AI.agent.model.model_list')
    model_map_raw = get_value(prefix + '_AI.agent.model.model_list_map')

    def collect_names(obj, names):
        if isinstance(obj, dict):
            if 'name' in obj and isinstance(obj['name'], str):
                names.add(obj['name'])
            for v in obj.values():
                collect_names(v, names)
        elif isinstance(obj, list):
            for i in obj:
                collect_names(i, names)

    names=set()
    for raw in [model_list_raw, model_map_raw]:
        if not raw:
            continue
        try:
            obj=json.loads(raw)
            collect_names(obj, names)
        except Exception:
            pass

    print('MODELS', len(names))
    for n in sorted(names):
        print('-', n)

conn.close()
