 199: function normalizeIntent(prompt: string, modeHint?: 'coding' | 'reasoning' | 'speed'): 'coding' | 'reasoning' | 'speed' {
 200:     if (modeHint) {
 201:         return modeHint;
 202:     }
 203: 
 204:     const lower = prompt.toLowerCase();
 205:     const hasReasoning = REASONING_KEYWORDS.some(key => lower.includes(key));
 206:     const hasCoding = CODING_KEYWORDS.some(key => lower.includes(key));
 207:     const hasSpeed = SPEED_KEYWORDS.some(key => lower.includes(key));
 208: 
 209:     if (hasReasoning) {
 210:         return 'reasoning';
 211:     }
 212:     if (hasCoding) {
 213:         return 'coding';
 214:     }
 215:     if (hasSpeed) {
 216:         return 'speed';
 217:     }
 218:     return 'coding';
