 221: function collectModelCandidates(input: unknown, out: Set<string>): void {
 222:     if (typeof input === 'string') {
 223:         if (MODEL_HINT_REGEX.test(input) && input.length <= 120) {
 224:             out.add(input);
 225:         }
 226:         return;
 227:     }
 228: 
 229:     if (Array.isArray(input)) {
 230:         for (const value of input) {
 231:             collectModelCandidates(value, out);
 232:         }
 233:         return;
 234:     }
 235: 
 236:     if (input && typeof input === 'object') {
 237:         const obj = input as Record<string, unknown>;
 238:         for (const value of Object.values(obj)) {
 239:             collectModelCandidates(value, out);
 240:         }
 241:     }
 242: }
