 244: function scoreModel(modelName: string, intent: 'coding' | 'reasoning' | 'speed'): number {
 245:     const name = modelName.toLowerCase();
 246: 
 247:     let score = 0;
 248:     if (intent === 'reasoning') {
 249:         if (name.includes('r1') || name.includes('reason') || name.includes('o1') || name.includes('o3') || name.includes('o4')) {
 250:             score += 8;
 251:         }
 252:         if (name.includes('deepseek') || name.includes('claude')) {
 253:             score += 3;
 254:         }
 255:     }
 256: 
 257:     if (intent === 'coding') {
 258:         if (name.includes('sonnet') || name.includes('code') || name.includes('gpt-4') || name.includes('gpt4') || name.includes('deepseek')) {
 259:             score += 7;
 260:         }
 261:         if (name.includes('claude') || name.includes('qwen')) {
 262:             score += 2;
 263:         }
 264:     }
 265: 
 266:     if (intent === 'speed') {
 267:         if (name.includes('mini') || name.includes('flash') || name.includes('haiku') || name.includes('turbo')) {
 268:             score += 8;
 269:         }
 270:         if (name.includes('gpt-4o')) {
 271:             score += 2;
 272:         }
 273:     }
 274: 
 275:     if (name.includes('preview') || name.includes('experimental')) {
 276:         score -= 1;
 277:     }
 278:     return score;
 279: }
