 281: function pickBestModel(models: string[], intent: 'coding' | 'reasoning' | 'speed'): string | null {
 282:     if (models.length === 0) {
 283:         return null;
 284:     }
 285: 
 286:     let best: { name: string; score: number } | null = null;
 287:     for (const model of models) {
