 152:     const lower = prompt.toLowerCase();
 153:     const hasReasoning = REASONING_KEYWORDS.some(key => lower.includes(key));
 154:     const hasCoding = CODING_KEYWORDS.some(key => lower.includes(key));
 155:     const hasSpeed = SPEED_KEYWORDS.some(key => lower.includes(key));
 156:     if (hasReasoning) {
 157:         return 'reasoning';
 158:     }
 159:     if (hasCoding) {
 160:         return 'coding';
 161:     }
 162:     if (hasSpeed) {
 163:         return 'speed';
 164:     }
 165:     return 'coding';
 166: }
 167: function collectModelCandidates(input, out) {
 168:     if (typeof input === 'string') {
 169:         if (MODEL_HINT_REGEX.test(input) && input.length <= 120) {
 170:             out.add(input);
 171:         }
 172:         return;
 173:     }
 174:     if (Array.isArray(input)) {
 175:         for (const value of input) {
 176:             collectModelCandidates(value, out);
 177:         }
 178:         return;
 179:     }
 180:     if (input && typeof input === 'object') {
 181:         const obj = input;
 182:         for (const value of Object.values(obj)) {
 183:             collectModelCandidates(value, out);
 184:         }
 185:     }
 186: }
 187: function scoreModel(modelName, intent) {
 188:     const name = modelName.toLowerCase();
 189:     let score = 0;
 190:     if (intent === 'reasoning') {
 191:         if (name.includes('r1') || name.includes('reason') || name.includes('o1') || name.includes('o3') || name.includes('o4')) {
 192:             score += 8;
 193:         }
 194:         if (name.includes('deepseek') || name.includes('claude')) {
 195:             score += 3;
 196:         }
 197:     }
 198:     if (intent === 'coding') {
 199:         if (name.includes('sonnet') || name.includes('code') || name.includes('gpt-4') || name.includes('gpt4') || name.includes('deepseek')) {
 200:             score += 7;
 201:         }
 202:         if (name.includes('claude') || name.includes('qwen')) {
 203:             score += 2;
 204:         }
 205:     }
 206:     if (intent === 'speed') {
 207:         if (name.includes('mini') || name.includes('flash') || name.includes('haiku') || name.includes('turbo')) {
 208:             score += 8;
 209:         }
 210:         if (name.includes('gpt-4o')) {
 211:             score += 2;
 212:         }
 213:     }
 214:     if (name.includes('preview') || name.includes('experimental')) {
 215:         score -= 1;
 216:     }
 217:     return score;
 218: }
 219: function pickBestModel(models, intent) {
 220:     if (models.length === 0) {
 221:         return null;
 222:     }
 223:     let best = null;
 224:     for (const model of models) {
 225:         const score = scoreModel(model, intent);
 226:         if (!best || score > best.score) {
 227:             best = { name: model, score };
 228:         }
 229:     }
 230:     return best?.name ?? models[0];
