import * as vscode from 'vscode';
import * as http from 'http';
import * as WebSocket from 'ws';

let server: http.Server | undefined;
let wss: WebSocket.Server | undefined;

type JsonValue = string | number | boolean | null | JsonObject | JsonValue[];
type JsonObject = { [key: string]: JsonValue };

interface AutoSelectModelPayload {
    action: 'auto_select_model';
    prompt?: string;
    modeHint?: 'coding' | 'reasoning' | 'speed';
    dryRun?: boolean;
}

interface ExecuteCommandPayload {
    action: 'execute_command';
    command: string;
    args?: JsonValue[];
}

interface TriggerTaskPayload {
    action: 'trigger_task';
    subagent?: string;
    prompt?: string;
}

type IncomingPayload = AutoSelectModelPayload | ExecuteCommandPayload | TriggerTaskPayload | JsonObject;

interface AutoSelectionResult {
    intent: 'coding' | 'reasoning' | 'speed';
    selectedModel: string | null;
    candidateModels: string[];
    usedSetConfig: boolean;
    setConfigSucceeded: boolean;
    details: string[];
}

const MODEL_HINT_REGEX = /(gpt|claude|gemini|deepseek|qwen|llama|mistral|sonnet|haiku|pro|flash|turbo|r1|o1|o3|o4)/i;
const REASONING_KEYWORDS = [
    'analyze', 'analysis', 'architecture', 'design', 'reason', 'deep', 'complex', 'optimiz',
    '分析', '架构', '设计', '复杂', '推理', '优化', '排查', '诊断'
];
const CODING_KEYWORDS = [
    'code', 'implement', 'build', 'fix', 'refactor', 'debug', 'test', 'patch',
    '写代码', '实现', '修复', '重构', '调试', '测试', '补丁'
];
const SPEED_KEYWORDS = [
    'quick', 'brief', 'summarize', 'draft', 'simple', 'fast',
    '快速', '简短', '总结', '草稿', '简单'
];

export function activate(context: vscode.ExtensionContext) {
    console.log('POC Trae WebSocket Extension is now active!');

    server = http.createServer((req, res) => {
        if (req.method === 'GET' && req.url === '/health') {
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ status: 'ok', worker: 'Trae WebSocket Engine' }));
            return;
        }

        if (req.method === 'GET' && req.url === '/api/commands') {
            void vscode.commands.getCommands(true)
                .then(commands => {
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ total: commands.length, commands }));
                })
                .catch(err => {
                    res.writeHead(500, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({ error: String(err) }));
                });
            return;
        }

        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Not Found (Please use ws://...)');
    });

    try {
        wss = new WebSocket.Server({ server });

        wss.on('connection', (ws: WebSocket) => {
            console.log('Codex Brain connected via WebSocket!');
            ws.send(JSON.stringify({ type: 'connected', message: 'Hello from Trae Worker!' }));

            const diagDisposable = vscode.languages.onDidChangeDiagnostics(event => {
                const allDiagnostics = event.uris.map(uri => {
                    const diags = vscode.languages.getDiagnostics(uri);
                    return {
                        file: uri.fsPath,
                        errors: diags
                            .filter(d => d.severity === vscode.DiagnosticSeverity.Error)
                            .map(d => ({
                                line: d.range.start.line + 1,
                                message: d.message
                            }))
                    };
                }).filter(group => group.errors.length > 0);

                if (allDiagnostics.length > 0) {
                    ws.send(JSON.stringify({
                        type: 'system_diagnostics_report',
                        data: allDiagnostics
                    }));
                }
            });
            context.subscriptions.push(diagDisposable);

            const saveDisposable = vscode.workspace.onDidSaveTextDocument(doc => {
                ws.send(JSON.stringify({
                    type: 'file_saved',
                    file: doc.uri.fsPath,
                    content_preview: doc.getText().substring(0, 150) + '... '
                }));
            });
            context.subscriptions.push(saveDisposable);

            ws.on('message', async (message: string) => {
                try {
                    const payload = JSON.parse(message.toString()) as IncomingPayload;
                    console.log('Received payload:', payload);

                    if (payload.action === 'trigger_task') {
                        const taskPayload = payload as TriggerTaskPayload;
                        const subagent = (taskPayload.subagent ?? 'worker').trim();
                        const prompt = (taskPayload.prompt ?? '').trim();

                        vscode.window.showInformationMessage(`[Trae Worker] 收到任务 ${subagent}: ${prompt}`);
                        ws.send(JSON.stringify({
                            type: 'action_receipt',
                            status: 'success',
                            message: `指令 [${subagent}] 已签收，开始执行`,
                            payload: taskPayload
                        }));
                        return;
                    }

                    if (payload.action === 'execute_command') {
                        const executePayload = payload as ExecuteCommandPayload;
                        const command = (executePayload.command ?? '').trim();
                        if (!command) {
                            ws.send(JSON.stringify({
                                type: 'command_result',
                                status: 'failed',
                                message: 'command is required'
                            }));
                            return;
                        }

                        const args = Array.isArray(executePayload.args) ? executePayload.args : [];
                        const result = await executeCommandSafely(command, args);
                        ws.send(JSON.stringify({
                            type: 'command_result',
                            status: result.ok ? 'success' : 'failed',
                            command,
                            args,
                            result: result.value,
                            error: result.error
                        }));
                        return;
                    }

                    if (payload.action === 'auto_select_model') {
                        const modelPayload = payload as AutoSelectModelPayload;
                        const result = await autoSelectModel(modelPayload);
                        ws.send(JSON.stringify({
                            type: 'model_selection_result',
                            status: result.setConfigSucceeded || modelPayload.dryRun ? 'success' : 'partial',
                            data: result
                        }));
                        return;
                    }

                    const actionName = (payload as { action?: string }).action ?? 'unknown';
                    ws.send(JSON.stringify({ type: 'error', message: `Unsupported action: ${actionName}` }));
                } catch {
                    ws.send(JSON.stringify({ type: 'error', message: 'Invalid command payload' }));
                }
            });

            ws.on('close', () => {
                console.log('Codex Brain disconnected');
            });
        });

        server.listen(9090, '127.0.0.1', () => {
            console.log('Trae WebSocket API Server listening on ws://127.0.0.1:9090');
            vscode.window.showInformationMessage('Trae WebSocket channel active (0.0.5) on 9090');
        });
    } catch (err) {
        vscode.window.showErrorMessage('Trae channel startup failed: ' + err);
    }
}

function normalizeIntent(prompt: string, modeHint?: 'coding' | 'reasoning' | 'speed'): 'coding' | 'reasoning' | 'speed' {
    if (modeHint) {
        return modeHint;
    }

    const lower = prompt.toLowerCase();
    const hasReasoning = REASONING_KEYWORDS.some(key => lower.includes(key));
    const hasCoding = CODING_KEYWORDS.some(key => lower.includes(key));
    const hasSpeed = SPEED_KEYWORDS.some(key => lower.includes(key));

    if (hasReasoning) {
        return 'reasoning';
    }
    if (hasCoding) {
        return 'coding';
    }
    if (hasSpeed) {
        return 'speed';
    }
    return 'coding';
}

function collectModelCandidates(input: unknown, out: Set<string>): void {
    if (typeof input === 'string') {
        if (MODEL_HINT_REGEX.test(input) && input.length <= 120) {
            out.add(input);
        }
        return;
    }

    if (Array.isArray(input)) {
        for (const value of input) {
            collectModelCandidates(value, out);
        }
        return;
    }

    if (input && typeof input === 'object') {
        const obj = input as Record<string, unknown>;
        for (const value of Object.values(obj)) {
            collectModelCandidates(value, out);
        }
    }
}

function scoreModel(modelName: string, intent: 'coding' | 'reasoning' | 'speed'): number {
    const name = modelName.toLowerCase();

    let score = 0;
    if (intent === 'reasoning') {
        if (name.includes('r1') || name.includes('reason') || name.includes('o1') || name.includes('o3') || name.includes('o4')) {
            score += 8;
        }
        if (name.includes('deepseek') || name.includes('claude')) {
            score += 3;
        }
    }

    if (intent === 'coding') {
        if (name.includes('sonnet') || name.includes('code') || name.includes('gpt-4') || name.includes('gpt4') || name.includes('deepseek')) {
            score += 7;
        }
        if (name.includes('claude') || name.includes('qwen')) {
            score += 2;
        }
    }

    if (intent === 'speed') {
        if (name.includes('mini') || name.includes('flash') || name.includes('haiku') || name.includes('turbo')) {
            score += 8;
        }
        if (name.includes('gpt-4o')) {
            score += 2;
        }
    }

    if (name.includes('preview') || name.includes('experimental')) {
        score -= 1;
    }
    return score;
}

function pickBestModel(models: string[], intent: 'coding' | 'reasoning' | 'speed'): string | null {
    if (models.length === 0) {
        return null;
    }

    let best: { name: string; score: number } | null = null;
    for (const model of models) {
        const score = scoreModel(model, intent);
        if (!best || score > best.score) {
            best = { name: model, score };
        }
    }
    return best?.name ?? models[0];
}

function safeStringify(value: unknown): string {
    try {
        return JSON.stringify(value);
    } catch {
        return String(value);
    }
}

function deepClone<T>(value: T): T {
    return JSON.parse(JSON.stringify(value)) as T;
}

function mutateModelFields(template: unknown, selectedModel: string): unknown {
    if (!template || typeof template !== 'object') {
        return template;
    }

    const copy = deepClone(template);
    const stack: unknown[] = [copy];
    while (stack.length > 0) {
        const current = stack.pop();
        if (!current || typeof current !== 'object') {
            continue;
        }
        if (Array.isArray(current)) {
            for (const item of current) {
                stack.push(item);
            }
            continue;
        }

        const obj = current as Record<string, unknown>;
        for (const [key, value] of Object.entries(obj)) {
            if (typeof value === 'string' && key.toLowerCase().includes('model')) {
                obj[key] = selectedModel;
            } else if (value && typeof value === 'object') {
                stack.push(value);
            }
        }
    }
    return copy;
}

async function executeCommandSafely(command: string, args: unknown[]): Promise<{ ok: boolean; value: unknown; error?: string }> {
    try {
        const value = await vscode.commands.executeCommand(command, ...args);
        return { ok: true, value };
    } catch (error) {
        return {
            ok: false,
            value: null,
            error: String(error)
        };
    }
}

