  { value: '99.9%', label: 'Uptime Vision' },
  { value: '8x', label: 'Concurrent Waves' },
  { value: '20s', label: 'Guarded Timeout' }
];

export default function App() {
  const [mode, setMode] = useState('launch');
  const palette = useMemo(() => paletteByMode(mode), [mode]);

  useEffect(() => {
    const style = document.documentElement.style;
    style.setProperty('--surface', palette.surface);
    style.setProperty('--panel', palette.panel);
    style.setProperty('--accent', palette.accent);
    style.setProperty('--accent-soft', palette.accentSoft);
    style.setProperty('--text-primary', palette.primaryText);
    style.setProperty('--text-secondary', palette.secondaryText);
  }, [palette]);

  return (
    <div className="page-shell">
      <div className="grain" aria-hidden="true" />
      <header className="topbar">
        <p className="brand">TRAE AUTO UI</p>
        <button className="pill">Port 9999</button>
      </header>

      <main className="hero-grid">
        <section className="hero-card">
          <p className="eyebrow">Creative Frontend Studio</p>
          <h1>
            Build a front page
            <span>that feels handcrafted</span>
          </h1>
          <p className="lead">
            A bold React + Vite showcase with editorial typography, layered gradients,
            motion reveals, and responsive layout tuned for desktop and mobile.
          </p>

          <div className="mode-switch" role="tablist" aria-label="Theme tone">
            {modes.map((item) => (
              <button
                key={item.id}
                role="tab"
                aria-selected={mode === item.id}
                className={mode === item.id ? 'mode active' : 'mode'}
                onClick={() => setMode(item.id)}
              >
                {item.label}
              </button>
            ))}
          </div>
        </section>

        <aside className="stats-card">
          <p className="eyebrow">Runtime Snapshot</p>
          <ul>
            {stats.map((item) => (
              <li key={item.label}>
                <strong>{item.value}</strong>
                <span>{item.label}</span>
              </li>
            ))}
          </ul>
          <div className="pulse" aria-hidden="true" />
        </aside>
      </main>

      <section className="feature-strip" aria-label="Highlights">
        <article>
          <h2>Expressive Type</h2>
          <p>Headline rhythm with strong contrast and readable body copy.</p>
        </article>
        <article>
          <h2>Atmospheric Depth</h2>
          <p>Layered textures and gradient fields avoid flat, generic UI.</p>
        </article>
        <article>
          <h2>Purposeful Motion</h2>
          <p>Staggered reveal and hover dynamics bring the layout to life.</p>
        </article>
      </section>
    </div>
  );
}
