@'
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Instrument+Serif:ital@0;1&family=Manrope:wght@400;600;800&display=swap');

:root {
  --surface: #f5f1e8;
  --panel: #efe7da;
  --accent: #b63a2b;
  --accent-soft: #e7c6b8;
  --text-primary: #19130f;
  --text-secondary: #4f4339;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: 'Manrope', 'Segoe UI', sans-serif;
  background: radial-gradient(circle at 10% 10%, color-mix(in srgb, var(--accent) 18%, transparent), transparent 30%),
    radial-gradient(circle at 85% 80%, color-mix(in srgb, var(--accent-soft) 60%, transparent), transparent 40%),
    var(--surface);
  color: var(--text-primary);
}

.page-shell {
  width: min(1120px, 92vw);
  margin: 2rem auto;
  padding: 2rem;
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--text-primary) 18%, transparent);
  border-radius: 26px;
  background: linear-gradient(140deg, color-mix(in srgb, var(--surface) 82%, white), var(--panel));
  box-shadow: 0 28px 70px color-mix(in srgb, var(--text-primary) 15%, transparent);
  animation: reveal .9s ease-out both;
}

.grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(color-mix(in srgb, var(--text-primary) 8%, transparent) 1px, transparent 1px);
  background-size: 4px 4px;
  opacity: 0.25;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.brand {
  margin: 0;
  font-family: 'Bebas Neue', sans-serif;
  letter-spacing: .1em;
  font-size: 1.5rem;
}

.pill {
  border: 1px solid color-mix(in srgb, var(--accent) 60%, white);
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 18%, white);
  color: var(--text-primary);
  padding: .5rem 1rem;
  font-weight: 700;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 1.2rem;
}

.hero-card,
.stats-card,
.feature-strip article {
  border-radius: 20px;
  background: color-mix(in srgb, white 52%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--text-primary) 14%, transparent);
  padding: 1.4rem;
}

.eyebrow {
  margin: 0;
  font-size: .75rem;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

h1 {
  margin: .8rem 0;
  font-family: 'Instrument Serif', Georgia, serif;
  line-height: .98;
  font-size: clamp(2.2rem, 5vw, 4rem);
}

h1 span {
  display: block;
  color: var(--accent);
  font-style: italic;
}

.lead {
  margin: 0 0 1.2rem;
  color: var(--text-secondary);
  max-width: 62ch;
}

.mode-switch {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
}

.mode {
  border: 1px solid color-mix(in srgb, var(--text-primary) 20%, transparent);
  border-radius: 999px;
  background: transparent;
  padding: .48rem .95rem;
  font-weight: 700;
  color: var(--text-secondary);
  cursor: pointer;
  transition: .24s ease;
}

.mode.active,
.mode:hover {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
  transform: translateY(-1px);
}

.stats-card {
  position: relative;
  overflow: hidden;
}

.stats-card ul {
  list-style: none;
  padding: 0;
  margin: .8rem 0 0;
  display: grid;
  gap: .9rem;
}

.stats-card li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px dashed color-mix(in srgb, var(--text-primary) 20%, transparent);
  padding-bottom: .55rem;
}

.stats-card strong {
  font-size: 1.6rem;
  font-family: 'Bebas Neue', sans-serif;
  letter-spacing: .04em;
}

.stats-card span {
  color: var(--text-secondary);
  font-weight: 600;
}

.pulse {
  position: absolute;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  right: -45px;
  bottom: -45px;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 32%, transparent), transparent 68%);
  animation: pulse 3s ease-in-out infinite;
}

.feature-strip {
  margin-top: 1.2rem;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.feature-strip h2 {
  margin: 0 0 .45rem;
  font-family: 'Bebas Neue', sans-serif;
  letter-spacing: .05em;
  font-size: 1.35rem;
}

.feature-strip p {
  margin: 0;
  color: var(--text-secondary);
}

.feature-strip article {
  animation: rise .8s ease both;
}

.feature-strip article:nth-child(2) {
  animation-delay: .12s;
}

.feature-strip article:nth-child(3) {
  animation-delay: .24s;
}

@keyframes reveal {
  from {
    opacity: 0;
    transform: translateY(22px) scale(.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: .75;
  }
  50% {
    transform: scale(1.08);
    opacity: 1;
  }
}

@media (max-width: 900px) {
  .page-shell {
    padding: 1.2rem;
    margin: 1rem auto;
  }

  .hero-grid,
  .feature-strip {
    grid-template-columns: 1fr;
  }
}
